//! The topology port against scenes recorded from the real `topojson-server`.
//!
//! Generated by `rust/codegen/generate-topology-scenes.mjs`: 600 randomised scenes on a
//! small grid, plus hand-built cases for each situation the algorithm's own comments name.
//! Arcs and the per-geometry arc references must match exactly, including their order and
//! sign, since the merge step downstream is driven by arc ids.

use osd_normalize::topology::{InputGeometry, TopoGeometry, topology};
use osd_store::FixedCoord;
use serde::Deserialize;

#[derive(Deserialize)]
struct Scenes {
    scenes: Vec<Scene>,
}

#[derive(Deserialize)]
struct Scene {
    input: Vec<RawGeometry>,
    arcs: Vec<Vec<[i32; 2]>>,
    geometries: Vec<RawTopoGeometry>,
}

#[derive(Deserialize)]
struct RawGeometry {
    #[serde(rename = "type")]
    kind: String,
    coordinates: serde_json::Value,
}

#[derive(Deserialize)]
struct RawTopoGeometry {
    #[serde(rename = "type")]
    kind: String,
    arcs: serde_json::Value,
}

fn coord([lng, lat]: [i32; 2]) -> FixedCoord {
    FixedCoord { lng, lat }
}

fn input(raw: &RawGeometry) -> InputGeometry {
    match raw.kind.as_str() {
        "LineString" => {
            let points: Vec<[i32; 2]> = serde_json::from_value(raw.coordinates.clone()).unwrap();
            InputGeometry::Line(points.into_iter().map(coord).collect())
        }
        "Polygon" => {
            let rings: Vec<Vec<[i32; 2]>> =
                serde_json::from_value(raw.coordinates.clone()).unwrap();
            InputGeometry::Polygon(
                rings
                    .into_iter()
                    .map(|ring| ring.into_iter().map(coord).collect())
                    .collect(),
            )
        }
        other => panic!("unexpected geometry type {other}"),
    }
}

fn expected(raw: &RawTopoGeometry) -> TopoGeometry {
    match raw.kind.as_str() {
        "LineString" => TopoGeometry::Line(serde_json::from_value(raw.arcs.clone()).unwrap()),
        "Polygon" => TopoGeometry::Polygon(serde_json::from_value(raw.arcs.clone()).unwrap()),
        other => panic!("unexpected geometry type {other}"),
    }
}

#[test]
fn every_recorded_scene_is_reproduced_exactly() {
    let scenes: Scenes = serde_json::from_str(include_str!("topology_scenes.json")).unwrap();
    assert!(scenes.scenes.len() >= 600, "scene file looks truncated");

    let mut failures = Vec::new();
    for (n, scene) in scenes.scenes.iter().enumerate() {
        let geometries: Vec<InputGeometry> = scene.input.iter().map(input).collect();
        let actual = match topology(&geometries) {
            Ok(actual) => actual,
            Err(error) => {
                failures.push(format!("scene {n}: {error}"));
                continue;
            }
        };

        let want_arcs: Vec<Vec<FixedCoord>> = scene
            .arcs
            .iter()
            .map(|arc| arc.iter().copied().map(coord).collect())
            .collect();
        let want_geometries: Vec<TopoGeometry> = scene.geometries.iter().map(expected).collect();

        if actual.arcs != want_arcs || actual.geometries != want_geometries {
            failures.push(format!(
                "scene {n}: input {:?}\n  actual arcs {:?}\n  actual refs {:?}\n  want arcs   {:?}\n  want refs   {:?}",
                geometries, actual.arcs, actual.geometries, want_arcs, want_geometries
            ));
        }
        if failures.len() >= 5 {
            break;
        }
    }
    assert!(failures.is_empty(), "\n{}", failures.join("\n"));
}
